  fun getQuestionsForGroups(groups: Set<ModalGroup>): List<QuizQuestion> =
    if (ModalGroup.ALL in groups) allQuestions
    else allQuestions.filter { it.group in groups }

  fun getModalDefinition(key: String, fallbackCategory: String): ModalDefinition {
    val normalized = key.trim().lowercase()
    return modalDefinitions[normalized] ?: ModalDefinition(
      key = normalized,
      name = key,
      role = fallbackCategory,
      structure = "Sujeito + modal + verbo principal",
      contrast = ""
    )
  }

  fun findModalDefinitionOrNull(key: String): ModalDefinition? =
    modalDefinitions[key.trim().lowercase()]
}
